#include <bits/stdc++.h>
using namespace std;

long computeAnswer(long n) {
    int maxLen = (int)4e5;
    vector<long> upperPart(maxLen, 0);
    vector<long> lowerPart(maxLen, 0);
    for (int i = 1; i < maxLen; ++i) {
        lowerPart[i] = i;
        upperPart[i] = n / i;
    }
    vector<bool> primeFlags(maxLen, true);
    primeFlags[0] = false;
    primeFlags[1] = false;

    vector<int> primes;
    for (int i = 2; i < maxLen; ++i) {
        if (!primeFlags[i]) continue;
        primes.push_back(i);
        for (int j = i * 2; j < maxLen; j += i) {
            primeFlags[j] = false;
        }
    }

    for (size_t index = 0; index < primes.size(); ++index) {
        int p = primes[index];
        for (int i = 1; i < maxLen && n / i >= (long long)p * p; ++i) {
            long long val = (long long)p * i;
            if (val < maxLen) {
                upperPart[i] -= (upperPart[(int)val] - (index + 1));
            } else {
                lowerPart[(int)(n / i / p)] -= (lowerPart[(int)(n / i / p)] - (index + 1));
            }
        }
        for (int i = maxLen - 1; i >= (long long)p * p; --i) {
            lowerPart[i] -= lowerPart[i / p] - (index + 1);
        }
    }

    long totalPrimesCount = 0;
    for (auto p : primes) {
        if ((long long)p * p > n) break;
        if ((long long)p * p * p <= n && (long long)p * p * p > 0) {
            totalPrimesCount++;
        }
        if (n / p > p) {
            if (p < maxLen)
                totalPrimesCount += upperPart[p] - lowerPart[p];
            else
                totalPrimesCount += lowerPart[(int)(n / p)] - lowerPart[p];
        }
    }
    return totalPrimesCount;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long inputNumber;
    cin >> inputNumber;
    cout << computeAnswer(inputNumber) << "\n";
    return 0;
}

